INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-014', 'EG', 'P3', 'OPEN', NULL, NULL, 'GAP-010 RESOLVED 2026-09-18: REF-01001 IS NOT Co-1, AND PARAMETER 3 REMAINS A PROXY DETERMINATION. Full text retrieved via the MDPI CDN host after www.mdpi.com refused the DOI, the versioned PDF URL and WebFetch with an Akamai 403 (the paper is gold OA, CC BY -- the block was an edge rule against the datacentre IP, not a paywall). The paper answers the question in its own words, three times. METHODS: ''People with disabilities were included in this research through the Croatian Association of Paraplegics and Tetraplegics (HUPT) SO THAT THEIR ABILITY TO OVERCOME SPECIFIC SLOPES on the macadam surface of the trails COULD BE MEASURED.'' RESULTS: ''This test was carried out with the COOPERATION of the HUPT association and included eight people: four women and four men of different ages. IT TESTED how long people in wheelchairs could travel on different slopes.'' ACKNOWLEDGMENTS: the authors ''wish to THANK the Maksimir Public Institution and the Croatian Association of Paraplegics and Tetraplegics for all their support'' -- thanked, not credited; all five authors are Faculty of Forestry and Wood Technology, University of Zagreb. Throughout, the disabled people are ''test subjects'', ''subjects'' and ''respondents''. So the HUPT involvement is PARTICIPATION AS SUBJECTS with a disabled people''s organisation facilitating recruitment and access. Under D-0178 that is not co-production, and under CLAUDE.md section 6 the Co-1 warrant IS co-production. The T3 tier the ratified ladder derived (clinical + lower_control) STANDS. CONSEQUENCE: specification 8''s falsification condition -- ''Overturned if a source states a value for this parameter at an anchoring tier'' -- is NOT met, and no re-determination is owed. THE CAUTION WAS RIGHT: batch 15 declined to claim Co-1 on the abstract''s ambiguous ''included in the implementation of the research'', and the full text shows that claim would have been FALSE. Claiming the tier on that sentence would have been the failure CLAUDE.md section 6 calls the worst available here, and it would have lifted parameter 3 off proxy on a fabricated warrant. WHAT THE FULL READ DID CONFIRM: both figures, in the Results rather than the abstract and in a stronger form -- ''the maximum longitudinal slope for Category 1 trails allowing independent movement was defined as 5.50%, while a 9.01% slope was determined as the maximum longitudinal slope above which independent movement is not enabled''. Extractions 42 and 43 moved skim/preliminary to full-read/verified; the values did not change.', '2026-09-18 05:40', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 05:40', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);

